70: func (db *DB) RaiseDecision(ctx context.Context, request DecisionRequest) (Decision, error) {
71: 	if request.ProjectID < 1 || request.TaskID < 1 || strings.TrimSpace(request.Origin) == "" || strings.TrimSpace(request.Question) == "" || len(request.Options) < 1 {
72: 		return Decision{}, fmt.Errorf("decision requires a Project, Task, origin, question and at least one option")
73: 	}
74: 	switch request.Kind {
75: 	case "merge_ready", "recovery", "worker_exited", "review", "review_cap", "worker_question", "orphan", "pr_closed", "dependency", "teardown_dependants", "quota", "budget", "review_dispute":
76: 	default:
77: 		return Decision{}, fmt.Errorf("invalid Decision kind %q", request.Kind)
78: 	}
79: 	if len(request.Evidence) > 64*1024 {
80: 		return Decision{}, fmt.Errorf("decision evidence exceeds the 64 KiB limit")
81: 	}
82: 	if request.Kind == "review_dispute" && (len(request.Evidence) == 0 || !slices.Equal(request.Options, []string{"withdraw", "keep"})) {
83: 		return Decision{}, fmt.Errorf("review dispute Decisions require evidence and the withdraw, keep options")
84: 	}
85: 	if request.Kind != "review_dispute" && len(request.Evidence) > 0 {
86: 		return Decision{}, fmt.Errorf("evidence is supported only for review dispute Decisions")
